CREATE OR REPLACE FUNCTION better_supabase.complete_refund(refund uuid, status text, provider_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
