declare
  v_me uuid := auth.uid();
  v_size integer := least(greatest(coalesce(my_subjects.page_size, 100), 1), 200);
  v_after_type text := split_part(my_subjects.cursor, ':', 1);
  v_after_id text := substr(my_subjects.cursor, length(split_part(my_subjects.cursor, ':', 1)) + 2);
  v_items jsonb;
  v_count integer;
begin
  if v_me is null then
    return jsonb_build_object('items', '[]'::jsonb, 'nextCursor', null);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'subjectType', p.subject_type, 'subjectId', p.subject_id,
      'organizationId', p.tenant, 'roles', p.roles, 'endsOn', p.ends_on,
      'emergency', p.emergency,
      'title', "better_supabase"."subject_title"(p.subject_type, p.subject_id),
      'url', "better_supabase"."subject_url"(p.subject_type, p.subject_id))
    order by p.subject_type, p.subject_id), '[]'::jsonb), count(*)
  into v_items, v_count
  from (
    select m."subject_type" as subject_type, m."subject_id" as subject_id,
      min(m."tenant_id"::text) as tenant,
      jsonb_agg(distinct m."role") as roles,
      case when bool_or(m."ends_on" is null) then null else max(m."ends_on") end as ends_on,
      bool_or(m."emergency") as emergency
    from "better_supabase"."subject_members" m
    where m."tenant_id" = my_subjects.tenant
      and (my_subjects.subject_type is null or m."subject_type" = my_subjects.subject_type)
      and (my_subjects.cursor is null
        or (m."subject_type", m."subject_id") > (v_after_type, v_after_id))
      and (m."user_id" = v_me or (m."team_id" is not null and m."team_id" in (select "better_supabase"."team_ids_of"(v_me))))
        and (m."starts_on" is null or m."starts_on" <= current_date)
        and (m."ends_on" is null or m."ends_on" >= current_date)
        and (m."ends_at" is null or m."ends_at" > now())
    group by m."subject_type", m."subject_id"
    order by m."subject_type", m."subject_id"
    limit v_size
  ) p;
  return jsonb_build_object(
    'items', v_items,
    'nextCursor', case when v_count = v_size
      then (v_items -> -1 ->> 'subjectType') || ':' || (v_items -> -1 ->> 'subjectId')
      else null end);
end;

declare
  v_period text;
  v_n bigint;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  v_period := case p_entity
    when 'drive_document' then ''
    when 'drive_document_sop' then ''
    when 'donation_receipt' then ''
    when 'risk' then ''
    when 'case' then to_char(next_number.at at time zone 'utc', 'YYYY')
    when 'inspection' then to_char(next_number.at at time zone 'utc', 'YYYY')
    when 'production_order' then to_char(next_number.at at time zone 'utc', 'YYYY')
    else null
  end;
  if v_period is null then
    raise exception 'unknown number sequence' using errcode = '22023', hint = 'NUMBER_ENTITY_UNKNOWN';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_number_assign"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using next_number.tenant, p_entity, v_period;
    end if;
  end;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(next_number.tenant::text || ':' || p_entity || ':' || v_period, 0));
  insert into "better_supabase"."number_sequences" ("tenant_id", "entity", "period", "last_number")
  values (next_number.tenant, p_entity, v_period, 1)
  on conflict ("tenant_id", "entity", "period")
  do update set "last_number" = "better_supabase"."number_sequences"."last_number" + 1, "updated_at" = now()
  returning "last_number" into v_n;
  perform "better_supabase".emit_event('number.assigned', jsonb_build_object('organizationId', next_number.tenant, 'entity', p_entity, 'period', v_period, 'number', v_n), 'number-sequences/' || p_entity, (next_number.tenant)::text, null, 'better-supabase/numbering');
  perform better_supabase.audit_event(
    event_type => 'number.assigned',
    category => 'data',
    target_type => 'number_sequence',
    record_id => p_entity,
    summary => 'assigned ' || v_n::text,
    tenant => (next_number.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', next_number.tenant, 'entity', p_entity, 'period', v_period, 'number', v_n)
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_number_assign"(uuid, text, bigint)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::bigint)', v_hook::oid::regproc)
        using next_number.tenant, p_entity, v_n;
    end if;
  end;
  return v_n;
end;

