CREATE OR REPLACE FUNCTION better_supabase.record_invoice_payment(invoice uuid, amount bigint, currency text, paid_at timestamp with time zone, method text, reference text, note text DEFAULT NULL::text, actor jsonb DEFAULT NULL::jsonb, reason text DEFAULT NULL::text)
