  );
    declare
    v_hook regprocedure := to_regprocedure('"public"."after_qualification_revoke"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
